    run: (_key, options) => {
      pending = (async () => {
        options.onOptimistic?.()
        observed.push(store.getState().workItemsCache[key]?.data?.map((row) => row.labels) ?? [])
        try {
          await options.mutate()
          return true
        } catch {
          options.onRevert?.()
