import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
const cwd = process.cwd()
const root = path.join(cwd, '.tmp/fork-hosted-identity-independent')
const hash = b => crypto.createHash('sha256').update(b).digest('hex')
const pins = []
const artifacts = new Map()
const jsonSeen = new Set()
const receipts = []
const sourceObservations = []
const seeds = [
  '.issue-sweep/hosted-identity-frozen-source.json',
  '.issue-sweep/hosted-identity-proof-manifest.json',
  '.issue-sweep/repair-before-regressions-receipt.json',
  '.issue-sweep/repair-after-regressions-receipt.json',
  '.issue-sweep/hosted-b210-preimage-manifest.json',
