  '.issue-sweep/config-race-independent-manifest.json',
  '.issue-sweep/review-b210-immutable/fork-repaired-independent-review.md',
  '.issue-sweep/review-b210-immutable/fork-repaired-independent-manifest.json',
  '.issue-sweep/hosted-identity-bounded-commit-credit.log',
  '.issue-sweep/recovery-contributor-pr.json',
  '.issue-sweep/contributor.patch'
]
function inspect(p, expectedHash, expectedBytes, origin) {
  const absolute = path.resolve(cwd, p)
  if (!absolute.startsWith(cwd + path.sep)) {
    pins.push({ path: p, expectedHash, origin, excluded: 'outside child' })
    return
  }
  if (!fs.existsSync(absolute) || !fs.statSync(absolute).isFile()) {
    pins.push({ path: p, expectedHash, origin, missing: true })
    return
  }
  let item = artifacts.get(p)
  if (!item) {
    const b = fs.readFileSync(absolute)
    item = { path: p, bytes: b.length, sha256: hash(b) }
    artifacts.set(p, item)
  }
  if (expectedHash) pins.push({ ...item, expectedHash, expectedBytes, origin, matches: item.sha256 === expectedHash && (expectedBytes == null || item.bytes === expectedBytes) })
  if (p.endsWith('.json') && !jsonSeen.has(p) && !p.includes('independent-manifest')) {
    jsonSeen.add(p)
    const obj = JSON.parse(fs.readFileSync(absolute, 'utf8'))
    if (Array.isArray(obj.argv)) receipts.push({ path: p, argv: obj.argv, exitCode: obj.exit_code ?? obj.exitCode, env: obj.env ?? obj.environment, log: obj.log, sourceUnchanged: obj.source_unchanged_during_command ?? obj.sourceUnchangedDuringCommand, sourceKeys: Object.keys(obj.before ?? obj.sourceBefore ?? {}) })
    walk(obj, p)
  }
}
function walk(o, origin) {
  if (!o || typeof o !== 'object') return
  if (Array.isArray(o)) { o.forEach(x => walk(x, origin)); return }
  const digest = o.sha256 ?? o.sha_256
  if (typeof o.path === 'string' && typeof digest === 'string') {
    if (o.path.startsWith('src/') || o.path.startsWith('config/')) {
      sourceObservations.push({ ...o, origin, classification: 'source snapshot at evidence time, not current artifact pin' })
      if (o.saved) inspect(o.saved, digest, o.bytes, origin)
    } else inspect(o.path, digest, o.bytes, origin)
  }
  if (typeof o.log === 'string' && typeof (o.log_sha256 ?? o.logSha256) === 'string') inspect(o.log, o.log_sha256 ?? o.logSha256, null, origin)
  for (const v of Object.values(o)) walk(v, origin)
}
seeds.forEach(p => inspect(p, null, null, 'seed'))
const out = { at: new Date().toISOString(), role: 'independent hash audit of owner/historical inputs; not reviewer execution of those commands', seeds, artifacts: [...artifacts.values()], pins, receipts, sourceObservations }
fs.writeFileSync(path.join(root, 'evidence-audit.json'), JSON.stringify(out, null, 2) + '\n')
console.log(JSON.stringify({ artifacts: out.artifacts.length, pins: pins.length, sourceObservations: sourceObservations.length, mismatches: pins.filter(p => p.matches === false || p.missing || p.excluded), receipts: receipts.map(({ path, exitCode }) => ({ path, exitCode })) }, null, 2))

