const REPOSITORY_SLUG_RE = /^[A-Za-z0-9._-]+$/

export function isValidGitHubApiRepository(repository: unknown): repository is GitHubOwnerRepo {
  if (
    !repository ||
    typeof repository !== 'object' ||
    !('owner' in repository) ||
    !('repo' in repository)
