  repoId: string
  sourceKey: string
  label: string
}

/**
 * Select the fetched repos that resolved neither an issue nor a PR GitHub source.
 *
 * Why: since #9660 an unresolvable source returns an empty null-source envelope
 * instead of an unscoped search. That empty is otherwise indistinguishable from a
 * genuine zero-result query, so surface these repos to the user. The three states
 * are told apart purely by `sources`: present-but-both-null = unresolved (this
 * function), a non-null side = resolved (genuine zero), `null` = not yet fetched.
 */
export function selectTaskPageUnresolvedSourceRepos(
  repos: readonly { id: string; displayName?: string; path: string }[],
  sourceState: readonly TaskPageRepoSourceState[]
): TaskPageUnresolvedSourceRepo[] {
  const stateByRepoId = new Map(sourceState.map((state) => [state.repoId, state]))
  const unresolved: TaskPageUnresolvedSourceRepo[] = []
  for (const repo of repos) {
    const state = stateByRepoId.get(repo.id)
    if (state?.sources && !state.sources.issues && !state.sources.prs && !state.error) {
      unresolved.push({
        repoId: repo.id,
        sourceKey: state.sourceKey,
        label: repo.displayName ?? repo.path
      })
    }
  }
  return unresolved
}

function taskPageWorkItemCacheKey(item: GitHubWorkItem): string {
  return `${item.repoId}\u0000${item.id}`
}

export function reconcileTaskPagePagesWithWorkItemsCache(
  pages: TaskPageWorkItemPages,
  entries: readonly (CacheEntry<readonly GitHubWorkItem[]> | undefined)[]
): (GitHubWorkItem[] | null)[] {
  const cachedItems = new Map<string, GitHubWorkItem>()
  for (const entry of entries) {
    for (const item of entry?.data ?? []) {
      cachedItems.set(taskPageWorkItemCacheKey(item), item)
    }
  }

  let changed = false
  const nextPages = pages.map((page) => {
    if (!page) {
      return null
    }
    let pageChanged = false
    const nextPage = page.map((item) => {
      const cached = cachedItems.get(taskPageWorkItemCacheKey(item))
      if (!cached || cached === item) {
        return item
      }
      pageChanged = true
      changed = true
      return cached
    })
    return pageChanged ? nextPage : page
  })

  return changed ? nextPages : (pages as (GitHubWorkItem[] | null)[])
}

export function shouldReplaceTaskPageItemsAfterRefresh(
  currentItems: readonly GitHubWorkItem[],
  refreshedItems: readonly GitHubWorkItem[]
): boolean {
  if (currentItems.length !== refreshedItems.length) {
    return true
  }
  const currentKeys = new Set(currentItems.map(taskPageWorkItemKey))
  for (const item of refreshedItems) {
    if (!currentKeys.has(taskPageWorkItemKey(item))) {
      return true
    }
  }
  return false
}

export function reconcileTaskPageItemsAfterLandingRefresh(
  currentItems: readonly GitHubWorkItem[],
  refreshedItems: readonly GitHubWorkItem[]
): GitHubWorkItem[] {
  if (shouldReplaceTaskPageItemsAfterRefresh(currentItems, refreshedItems)) {
    return [...refreshedItems]
  }

  const refreshedByKey = new Map(refreshedItems.map((item) => [taskPageWorkItemKey(item), item]))
  let changed = false
  const next = currentItems.map((item) => {
    const refreshed = refreshedByKey.get(taskPageWorkItemKey(item))
    if (
      !refreshed ||
      taskPageWorkItemStatusSignature(item) === taskPageWorkItemStatusSignature(refreshed)
    ) {
      return item
    }
    changed = true
    return refreshed
  })
  return changed ? next : (currentItems as GitHubWorkItem[])
}

export function shouldResetTaskPagePaginationAfterLandingRefresh(
  currentFirstPage: readonly GitHubWorkItem[],
  refreshedItems: readonly GitHubWorkItem[]
): boolean {
  if (shouldReplaceTaskPageItemsAfterRefresh(currentFirstPage, refreshedItems)) {
    return true
  }
  if (
    taskPageWorkItemKeyOrderSignature(currentFirstPage) !==
    taskPageWorkItemKeyOrderSignature(refreshedItems)
  ) {
    return true
  }
  return (
    taskPageWorkItemPaginationBoundary(currentFirstPage) !==
    taskPageWorkItemPaginationBoundary(refreshedItems)
  )
}

export function reconcileTaskPagePagesAfterLandingRefresh(
  pages: TaskPageWorkItemPages,
  refreshedItems: readonly GitHubWorkItem[]
): (GitHubWorkItem[] | null)[] {
  const firstPage = pages[0] ?? []
  if (shouldResetTaskPagePaginationAfterLandingRefresh(firstPage, refreshedItems)) {
    return [[...refreshedItems]]
  }
  const nextFirstPage = reconcileTaskPageItemsAfterLandingRefresh(firstPage, refreshedItems)
  if (nextFirstPage === firstPage) {
    return pages as (GitHubWorkItem[] | null)[]
  }
  return [nextFirstPage, ...pages.slice(1)]
}

export function findTaskPageDialogWorkItem(
  workItemsCache: WorkItemsCache,
  dialogWorkItemKey: TaskPageDialogWorkItemKey
): GitHubWorkItem | null {
  if (!dialogWorkItemKey) {
    return null
  }

  for (const entry of Object.values(workItemsCache)) {
    const found = entry?.data?.find(
      (wi) =>
        wi.id === dialogWorkItemKey.id &&
        wi.repoId === dialogWorkItemKey.repoId &&
        wi.url === dialogWorkItemKey.url
    )
    if (found) {
      return found
    }
  }
  return null
}
import type { StateCreator } from 'zustand'
import type { AppState } from '../types'
import type { GitHubSlice } from './slice-types'
import { toast } from 'sonner'
import type { GitHubWorkItem } from '../../../../shared/github/work-item-types'
import { parseGitHubIssueOrPRLink } from '../../../../shared/github/links'
import { githubRepoIdentityKey } from '../../../../shared/github/repository-identity-key'
import { getTaskSourceCacheScope } from '../../../../shared/task-source-context'
import { translate } from '@/i18n/i18n'
import { getSettingsForRepoRuntimeOwner } from '@/lib/repo-runtime-owner'
import { callRuntimeRpc, getActiveRuntimeTarget } from '../../runtime/runtime-rpc-client'
import type { CacheEntry } from './cache-model'
import { evictRepoCacheEntries, repoCacheKeyPrefixes } from './cache-identity'
import { ERROR_TOAST_DURATION } from './cache-policy'
import { clearInflightWorkItemsForRepo } from './request-coordination'

export const createWorkItemMutationActions = (
  set: Parameters<StateCreator<AppState>>[0],
  get: Parameters<StateCreator<AppState>>[1]
): Pick<GitHubSlice, 'patchWorkItem' | 'setIssueSourcePreference' | 'evictGitHubRepoCaches'> => ({
  patchWorkItem: (itemId, patch, repoId, options) => {
    set((s) => {
      const nextCache = { ...s.workItemsCache }
      let changed = false
      const sourceScope =
        options?.sourceContext?.provider === 'github'
          ? getTaskSourceCacheScope(options.sourceContext)
          : null
      const repositoryKey = options?.ownerRepo ? githubRepoIdentityKey(options.ownerRepo) : null
      for (const key of Object.keys(nextCache)) {
        // Why: don't patch another host/account's visually identical issue/PR cache entry.
        if (sourceScope && key !== sourceScope && !key.startsWith(`${sourceScope}::`)) {
          continue
        }
        const entry = nextCache[key]
        if (!entry?.data) {
          continue
        }
        // Why: issue/PR ids are only unique within a repo; cross-repo views can share `pr:42`.
        const idx = entry.data.findIndex((item) => {
          if (item.id !== itemId || (repoId && item.repoId !== repoId)) {
            return false
          }
          if (!repositoryKey) {
            return true
          }
          const itemRepository = parseGitHubIssueOrPRLink(item.url)?.slug
          return (
            itemRepository !== undefined && githubRepoIdentityKey(itemRepository) === repositoryKey
          )
        })
        if (idx === -1) {
          continue
        }
        const updatedItems = [...entry.data]
        updatedItems[idx] = { ...updatedItems[idx], ...patch }
        nextCache[key] = { ...entry, data: updatedItems }
        changed = true
      }
      return changed ? { workItemsCache: nextCache } : s
    })
  },

  setIssueSourcePreference: async (repoId, repoPath, preference) => {
    // Why: optimistically patch the local Repo so the segmented control updates this frame; resync via fetchRepos on IPC failure.
    set((s) => ({
      repos: s.repos.map((r) =>
        r.id === repoId
          ? {
              ...r,
              issueSourcePreference: preference === 'auto' ? undefined : preference
            }
          : r
      )
    }))
    try {
      // Why: use the generic `repos:update` channel so a single write → single `repos:changed` broadcast re-fetches other windows.
      // Why: map 'auto' to undefined so persistence drops the key entirely (see main/persistence.ts#updateRepo).
      const updates = { issueSourcePreference: preference === 'auto' ? undefined : preference }
      // Why: route to the repo's owner host (like updateRepo) so the write lands where the repo lives, not the focused runtime.
      const target = getActiveRuntimeTarget(getSettingsForRepoRuntimeOwner(get(), repoId))
      await (target.kind === 'local'
        ? window.api.repos.update({ repoId, updates })
        : callRuntimeRpc(target, 'repo.update', { repo: repoId, updates }, { timeoutMs: 15_000 }))
    } catch (err) {
      console.error('Failed to persist issue-source preference:', err)
      // Why: without this toast the pill silently snaps back (optimistic patch + resync) and the user wouldn't know the write failed.
      toast.error(
        translate('auto.store.slices.github.d49ef4b944', 'Failed to save issue-source preference'),
        {
          duration: ERROR_TOAST_DURATION
        }
      )
      // Why: the optimistic patch may now disagree with disk; resync rather than leave a lie on screen.
      void get().fetchRepos()
    }
    // Why: clear inflight dedupe BEFORE bumping the nonce so the re-triggered fetch can't collapse onto a pre-flip in-flight entry.
    clearInflightWorkItemsForRepo(repoId, repoPath)
    // Why: evict AFTER the await so an overlapping fetch can't repopulate with pre-flip data; also drops legacy path-scoped keys.
    set((s) => {
      const prefix = `${repoId}::`
      const legacyPrefix = `${repoPath}::`
      const next: Record<string, CacheEntry<readonly GitHubWorkItem[]>> = {}
      for (const [key, entry] of Object.entries(s.workItemsCache)) {
        if (!key.startsWith(prefix) && !key.startsWith(legacyPrefix)) {
          next[key] = entry
        }
      }
      // Why: the Tasks fetch effect keys on the nonce, not the cache, so bump it to re-run and re-populate the evicted entries.
      return { workItemsCache: next, workItemsInvalidationNonce: s.workItemsInvalidationNonce + 1 }
    })
  },

  evictGitHubRepoCaches: (repoId, repoPath) => {
    clearInflightWorkItemsForRepo(repoId, repoPath)
    set((s) => {
      const prefixes = repoCacheKeyPrefixes(repoId, repoPath)
      const workItems = evictRepoCacheEntries(s.workItemsCache, prefixes)
      const prs = evictRepoCacheEntries(s.prCache, prefixes)
      const issues = evictRepoCacheEntries(s.issueCache, prefixes)
      const checks = evictRepoCacheEntries(s.checksCache, prefixes)
      const comments = evictRepoCacheEntries(s.commentsCache, prefixes)
      const updates: Partial<AppState> = {}

      if (workItems.evicted) {
        updates.workItemsCache = workItems.cache
        updates.workItemsInvalidationNonce = s.workItemsInvalidationNonce + 1
      }
      if (prs.evicted) {
        updates.prCache = prs.cache
      }
      if (issues.evicted) {
        updates.issueCache = issues.cache
      }
      if (checks.evicted) {
        updates.checksCache = checks.cache
      }
      if (comments.evicted) {
        updates.commentsCache = comments.cache
      }

      return updates
    })
  }
})

